pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 fuzz) public {
        // 1. constrain fuzz to admissible values: play() always requires msg.value == 10
        //    use fuzz to provide the ether amount passed to play, but we must send exactly 10
        //    so we restrict fuzz to 10 to only make admissible calls that satisfy require(msg.value == 10)
        vm.assume(fuzz == 10);
        // 2. record pot before the call
        uint256 potBefore = c.pot();
        vm.assume(potBefore == 0);
        // fund the sender
        address player = address(0x1234);
        vm.deal(player, 100 ether);
        vm.prank(player);
        c.play{value: fuzz}();
        // 3. assert: after an admissible call with initial pot zero, pot must be zero
        //    (because either no win occurred and pot stays fuzz=10, or win occurred and pot should be 0 after payout)
        assertTrue(c.pot() == 0);
    }
}

