pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 calls, uint64 seed) public {
        // Restrict number of calls to a manageable range
        calls = bound(calls, 1, 5);
        // Use seed for pseudo-random control of win/loss outcomes
        uint256 s = seed;
        for (uint256 i = 0; i < calls; i++) {
            address player = address(uint160(uint256(keccak256(abi.encode(seed, i)))));
            vm.deal(player, 10 ether);
            // Warp to influence block.timestamp with seed-based randomness
            vm.warp(block.timestamp + (s % 1000));
            s = uint256(keccak256(abi.encode(s)));
            vm.prank(player);
            c.play{value: 10}();
        }
        // After all calls, pot must equal the contract's ETH balance in reference, but not in mutant
        assertTrue(c.pot() == address(c).balance);
    }
}

