        // keccak256(abi.encodePacked(uint256 1, uint256 0)): let's compute off-chain: 0xb10e2d527612073b26eecdfd717e6a320cf44b4afac2b0732d9fcbe2b7fa0cf6 -> last byte 0xf6 = 246, 246%2=0 -> random=0.
        // Timestamp 2: 0x405787fa12a823e0f2b7631cc41b3ba8828b3321ca811111fa75cd3aa3bb5ace -> last byte 0xce=206, 206%2=0 -> random=0.
        // Timestamp 3: 0xc2575a0e9e593c00f959f8c92f12db2869c3395a3b0502d05e2516446f71f85b -> last byte 0x5b=91, 91%2=1 -> random=1 (loss).
        // So we warp to timestamp 3 and call play. That yields a losing play.
        // But we want fuzzSeed number of losing plays. We can loop and warp to 3 each time, but then block.timestamp doesn't change, so random is always the same (loss). Good.
        // So:
        vm.warp(3);
        vm.roll(0);
        for (uint i = 0; i < fuzzSeed; i++) {
            vm.deal(address(this), 10);
            vm.prank(address(this));
            c.play{value: 10}();
            // after each play, if it was a loss (random=1), pot should contain the sum of all previous losses + this one.
            // In reference C, pot increments on every play, so after k losses, pot = k*10.
            // In mutant, pot only increments on wins, so after k losses, pot = 0.
        }
        // After fuzzSeed losing plays, pot should be fuzzSeed * 10.
        assertTrue(c.pot() == fuzzSeed * 10);
    }
}

