pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public {
        c = new C();
    }

    function testFuzz_property(uint128 plays) public {
        // Bound to a reasonable number of plays; each play costs 10 wei, fee is 1 wei
        vm.assume(plays >= 1 && plays <= 1000);

        // Give the contract some ETH to avoid OutOfGas on transfers from an empty pot,
        // but we must keep the invariant about the bank’s balance.
        // The contract starts with 0 balance. We deal the player exactly the required msg.value per play.
        address player = address(0x1234);
        uint256 required = uint256(plays) * 10;
        vm.deal(player, required);

        // Record the bank's starting balance (bank is the deployer, i.e., address(this) in setUp context)
        address bank = c.bank();
        uint256 bankBefore = bank.balance;

        vm.startPrank(player);
        for (uint256 i = 0; i < plays; i++) {
            c.play{value: 10}();
        }
        vm.stopPrank();

        // After all plays, the bank must have received at least 1 wei for every win.
        // Count wins: each win resets pot to 0, so number of wins = number of times pot was reset.
        // However, we don’t count directly; we rely on the invariant:
        // Total fees paid to bank = (number of wins) * 1 wei.
        // The bank's balance increase is exact fees, because on a win the bank is transferred exactly 1 wei.
        // The mutant never transfers to the bank, so bank.balance == bankBefore always,
        // which violates the rule that bank.balance >= bankBefore + 1 for at least one win.
        // Since plays >= 1, with high probability there is at least one win, and the assertion will fail on the mutant.
        assertTrue(bank.balance > bankBefore);
    }
}

